package com.example

/**
 * Grade 11 History Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and provides distinct question variations across papers 1 to 30.
 */
object HistoryGrade11QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 11 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..6 -> "කෝට්ටේ රාජධානිය සහ හයවන පරාක්‍රමබාහු රජු" to run {
        val list = listOf(
          Quad("ශ්‍රී ලංකාව මුළුමනින්ම එක්සේසත් කළ කෝට්ටේ රාජධානියේ ශ්‍රේෂ්ඨතම රජතුමා කවුද?", listOf("හයවන පරාක්‍රමබාහු රජතුමා", "ධර්මපාල රජු", "බුවනෙකබාහු VII", "මායාදුන්නේ රජු"), 1, "වසර 55 ක් රජකම් කරමින් මුළු දිවයිනම එකම ධජයක් යටතට ගෙන ආවේ 6 වන පරාක්‍රමබාහු රජුය."),
          Quad("හයවන පරාක්‍රමබාහු රජු වෙනුවෙන් යාපනය ආර්ය චක්‍රවර්තී යටත් කර පාලනය කළ වීර කුමරු කවුද?", listOf("සපුමල් කුමාරයා (චෙම්පක පෙරුමාල්)", "අම්බුලුගල කුමරු", "වීදිය බණ්ඩාර", "ටිකිරි කුමරු"), 1, "සපුමල් කුමරු යාපනය ජයගෙන 'ශ්‍රී සංඝබෝධි බුවනෙකබාහු' නමින් යාපනයේ පාලකයා ලෙස කටයුතු කළේය."),
          Quad("හයවන පරාක්‍රමබාහු රජුගේ කාලයේ කඳුකරයේ ඇතිවූ 'ජෝතිය සිටු කැරැල්ල' මැඩපැවැත්වූයේ කවුරුන්ද?", listOf("අම්බුලුගල කුමරු", "සපුමල් කුමාරයා", "මායාදුන්නේ", "සේනාසම්මත වික්‍රමබාහු"), 1, "අම්බුලුගල කුමරු උඩරට කැරැල්ල සාර්ථකව මැඩපවත්වා කෝට්ටේ ආධිපත්‍යය තහවුරු කළේය."),
          Quad("හයවන පරාක්‍රමබාහු රජුගේ රාජ්‍ය අනුග්‍රහය ලත් තොටගමුවේ පිහිටි ප්‍රමුඛ බෞද්ධ අධ්‍යාපන මධ්‍යස්ථානය කුමක්ද?", listOf("විජයබා පිරිවෙන (තොටගමුව)", "පද්මාවතී පිරිවෙන", "සුනෙත්‍රාදේවී පිරිවෙන", "විද්‍යෝදය පිරිවෙන"), 1, "තොටගමුවේ ශ්‍රී රාහුල හිමියන් වැඩසිටි විජයබා පිරිවෙන පෙරදිග භාෂා හා විද්‍යාවන් ඉගැන්වූ ජාත්‍යන්තර කේන්ද්‍රස්ථානයකි."),
          Quad("හයවන පරාක්‍රමබාහු රජු සිය මෑණියන් වූ සුනෙත්‍රා දේවිය සිහිවීම පිණිස ඉදිකළ පිරිවෙන පිහිටියේ කොහේද?", listOf("පැපිලියාන සුනෙත්‍රාදේවී පිරිවෙන", "තොටගමුව", "කෑරගල", "වීදාගම"), 1, "පැපිලියානේ සුනෙත්‍රාදේවී පිරිවෙන මහා විහාරයක් ලෙස මනාව පවත්වාගෙන ගියේය."),
          Quad("කෝට්ටේ යුගයේදී මුළු ලක්දිවම ආවරණය වන පරිදි පැවති ඒකීය පාලන ක්‍රමය කුමක්ද?", listOf("අගනුවර කේන්ද්‍ර කරගත් ප්‍රාදේශීය යටත් පාලන ක්‍රමය", "ෆෙඩරල් ක්‍රමය", "විදේශීය යටත් විජිත පාලනය", "ගෝත්‍රික පාලනය"), 1, "යාපනය, වන්නිය හා උඩරට සියල්ල කෝට්ටේ සිංහාසනයට කප්පම් ගෙවමින් පාලනය විය.")
        )
        list[(slot - 1 + v).mod(list.size)]
      }
      in 7..12 -> "කෝට්ටේ යුගයේ සන්දේශ කාව්‍ය සාහිත්‍යය" to run {
        val list = listOf(
          Quad("කෝට්ටේ යුගයේ තොටගමුවේ ශ්‍රී රාහුල හිමියන් විසින් රචිත අග්‍රගණ්‍ය සන්දේශ කාව්‍යය කුමක්ද?", listOf("සැලලිහිණි සන්දේශය (සහ පරවි සන්දේශය)", "ගිරා සන්දේශය", "හංස සන්දේශය", "තිසර සන්දේශය"), 1, "කැලණියේ විභීෂණ දෙවියන් වෙත උලකුඩය දේවියට පුත් කුමරෙකු පතා සැලලිහිණි සන්දේශය රචනා කෙරිණි."),
          Quad("වීදාගම මෛත්‍රිය හිමියන් විසින් රචිත ලක්දිව සමාජ පරිහානිය හා දුර්ගුණ විවේචනය කරන කෘතිය කුමක්ද?", listOf("බුදුගුණාලංකාරය (සහ ලෝවැඩ සඟරාව)", "කාව්‍යශේඛරය", "ගුත්තිල කාව්‍යය", "සැලලිහිණි සන්දේශය"), 1, "වීදාගම හිමියන්ගේ ලෝවැඩ සඟරාව සහ බුදුගුණාලංකාරය උපදේශාත්මක බෞද්ධ සාහිත්‍යයේ මුදුන්මල්කඩකි."),
          Quad("ගුරු-ගෝල ගැටුම පාදක කරගනිමින් වෑත්තෑවේ හිමියන් විසින් රචිත විශිෂ්ට කාව්‍ය ග්‍රන්ථය කුමක්ද?", listOf("ගුත්තිල කාව්‍යය (Guttila Kavya)", "කාව්‍යශේඛරය", "කව්සිළුමිණ", "කුසජාතකය"), 1, "ගුත්තිල පඬිතුමා සහ මූසිලගේ වීණා වාදන තරඟය ඇසුරින් ගුත්තිල කාව්‍යය රචනා විය."),
